<?php $editing=$role!==null;$title=$editing?'Editar rol':'Nuevo rol'; ?><div class="page-heading"><div><p class="eyebrow">Administración</p><h1><?= $title ?></h1><p>Selecciona exactamente las operaciones autorizadas.</p></div><a class="btn btn-outline-secondary" href="<?= url('/roles') ?>">Cancelar</a></div><form class="panel form-narrow" method="post" action="<?= $editing?url('/roles/'.$role['id_rol'].'/editar'):url('/roles') ?>"><?= csrf_field() ?><div class="mb-3"><label class="form-label" for="nombre">Nombre *</label><input class="form-control" id="nombre" name="nombre" maxlength="50" value="<?= e($role['nombre']??'') ?>" required <?= ($role['id_rol']??0)==1?'readonly':'' ?>></div><div class="mb-4"><label class="form-label" for="descripcion">Descripción</label><textarea class="form-control" id="descripcion" name="descripcion" maxlength="255"><?= e($role['descripcion']??'') ?></textarea></div><fieldset><legend class="h6">Permisos</legend><?php foreach($permissions as $p): ?><div class="form-check permission-check"><input class="form-check-input" type="checkbox" name="permisos[]" value="<?= $p['id_permiso'] ?>" id="permiso-<?= $p['id_permiso'] ?>" <?= in_array((int)$p['id_permiso'],$selected,true)?'checked':'' ?>><label class="form-check-label" for="permiso-<?= $p['id_permiso'] ?>"><strong><?= e($p['nombre']) ?></strong><small><?= e($p['codigo']) ?></small></label></div><?php endforeach; ?></fieldset><button class="btn btn-primary mt-4">Guardar rol</button></form>

